pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        uint256 beforeCount;
        try c.depositsCount() returns (uint256 __r) { beforeCount = __r; } catch { return; }
        address beforeOwner;
        try c.owner() returns (address __r) { beforeOwner = __r; } catch { return; }
        uint beforeBalance = address(c).balance;
        try c.depositsCount() {} catch { return; }
        uint256 afterCount;
        try c.depositsCount() returns (uint256 __r) { afterCount = __r; } catch { return; }
        address afterOwner;
        try c.owner() returns (address __r) { afterOwner = __r; } catch { return; }
        uint afterBalance = address(c).balance;
        assertTrue(afterCount == beforeCount && afterBalance == beforeBalance && afterOwner == beforeOwner);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
